class RetentionCleanupServiceTest {@Test void activeMasterAndActiveLinkedDocumentsAreProtected(){var resumes=mock(ResumeVersionRepository.class);var letters=mock(CoverLetterRepository.class);var apps=mock(ApplicationRepository.class);var jobs=mock(JobRepository.class);var audits=mock(CleanupAuditRepository.class);var storage=mock(ResumeStorage.class);ResumeVersion master=new ResumeVersion();master.setMasterResume(true);when(resumes.findByCreatedAtBefore(any())).thenReturn(List.of(master));when(letters.findByCreatedAtBefore(any())).thenReturn(List.of());when(apps.findByUpdatedAtBefore(any())).thenReturn(List.of());when(jobs.findByStatusInAndUpdatedAtBefore(any(),any())).thenReturn(List.of());var service=new RetentionCleanupService(resumes,letters,apps,jobs,audits,storage,true,true,30,90,90,365);var result=service.run();assertEquals(0,result.candidates());verifyNoInteractions(storage);}}
